// Page objects generated by code (not the LLM) from the locator registry — the single locator source
// (salesforce-lightning-locators skill). Labels live here, never in tests. RE_VERIFY rows are kept as members but
// flagged, so Test Reviewer pass 2 can mark specs that use them REVIEW_REQUIRED.
import { createHash } from 'node:crypto';
import { join } from 'node:path';
import { z } from 'zod';
import { formatTypeScript } from '../../util/format.js';
import type { LocatorEntry } from '../../knowledge/locatorRegistry.js';
import { parseLocatorExpression } from './expression.js';

export interface PageDef {
  id: string;
  className: string;
  object: string;
  /** Root region expression (relative to `page`). */
  rootExpr: string;
  kind: 'record' | 'dialog';
  title: string;
}

/** Pages page objects are generated for (ids match the Application Explorer's PAGES). */
export const PAGE_DEFS: readonly PageDef[] = [
  {
    id: 'account-record',
    className: 'AccountRecordPage',
    object: 'Account',
    rootExpr: "getByRole('main')",
    kind: 'record',
    title: 'Account record page',
  },
  {
    id: 'contact-record',
    className: 'ContactRecordPage',
    object: 'Contact',
    rootExpr: "getByRole('main')",
    kind: 'record',
    title: 'Contact record page',
  },
  {
    id: 'contact-new',
    className: 'NewContactDialog',
    object: 'Contact',
    rootExpr: "getByRole('dialog', { name: 'New Contact' })",
    kind: 'dialog',
    title: 'New Contact dialog (from the Account Contacts related list)',
  },
];

export const CatalogMember = z.object({
  /** Member name in the page object (camelCase). */
  name: z.string(),
  /** `<pageId>.<name>` — what the test IR references. */
  ref: z.string(),
  kind: z.enum(['element', 'region']),
  role: z.string().optional(),
  accessibleName: z.string().optional(),
  fieldApiName: z.string().optional(),
  /** Accessible name of the closest named scope region (e.g. the "Contacts" related list). */
  scopeName: z.string().optional(),
  expression: z.string(),
  strategyRank: z.number().int().min(1).max(5),
  status: z.enum(['ACTIVE', 'RE_VERIFY']),
  registryElement: z.string().optional(),
  lastVerifiedAt: z.string().optional(),
});
export type CatalogMember = z.infer<typeof CatalogMember>;

export const CatalogPage = z.object({
  id: z.string(),
  className: z.string(),
  file: z.string(),
  object: z.string(),
  kind: z.enum(['record', 'dialog']),
  title: z.string(),
  rootExpr: z.string(),
  members: z.array(CatalogMember),
});
export type CatalogPage = z.infer<typeof CatalogPage>;

export const PageCatalog = z.object({
  org: z.string(),
  orgAlias: z.string(),
  environment: z.enum(['LIVE', 'FIXTURE']),
  persona: z.string(),
  generatedFrom: z.literal('locator-registry'),
  pages: z.array(CatalogPage),
});
export type PageCatalog = z.infer<typeof PageCatalog>;

const ROLE_SUFFIX: Record<string, string> = {
  button: 'Button',
  tab: 'Tab',
  link: 'Link',
  checkbox: 'Checkbox',
  article: 'RelatedList',
  tabpanel: 'Panel',
  group: 'Group',
  dialog: 'Dialog',
  menuitem: 'MenuItem',
  heading: 'Heading',
  grid: 'Grid',
};

export function camel(text: string): string {
  const words = text
    .replace(/&/g, ' and ')
    .replace(/[^A-Za-z0-9]+/g, ' ')
    .trim()
    .split(/\s+/)
    .filter(Boolean);
  const out = words
    .map((w, i) => (i === 0 ? w.charAt(0).toLowerCase() + w.slice(1) : w.charAt(0).toUpperCase() + w.slice(1)))
    .join('');
  return /^[0-9]/.test(out) ? `n${out}` : out || 'element';
}

/** Name for a registry row: field → camel(field); otherwise camel(scope + name) + role suffix. */
function memberName(e: LocatorEntry, scopeName: string | undefined, isRoot: (s: string) => boolean): string {
  const role = e.role ?? 'element';
  if (e.fieldApiName && (role === 'textbox' || role === 'combobox' || role === 'checkbox' || role === 'spinbutton')) {
    return camel((e.fieldApiName.split('.')[1] ?? e.fieldApiName).replace(/__c$/, ''));
  }
  const prefix = scopeName && !isRoot(scopeName) ? `${scopeName} ` : '';
  return camel(`${prefix}${e.accessibleName ?? e.element}`) + (ROLE_SUFFIX[role] ?? '');
}

function nameOfCall(expr: string): string | undefined {
  const calls = parseLocatorExpression(expr);
  const last = calls[calls.length - 1];
  const opts = last?.args[1];
  if (opts && typeof opts === 'object' && !(opts instanceof RegExp)) {
    const n = (opts as Record<string, unknown>)['name'];
    if (typeof n === 'string') return n;
  }
  return undefined;
}

function roleOfCall(expr: string): string | undefined {
  const calls = parseLocatorExpression(expr);
  const last = calls[calls.length - 1];
  return last?.method === 'getByRole' && typeof last.args[0] === 'string' ? last.args[0] : undefined;
}

/** Build the catalog of one org/persona from registry rows (ACTIVE + RE_VERIFY; RETIRED rows are dropped). */
export function buildCatalog(input: {
  entries: LocatorEntry[];
  org: string;
  orgAlias: string;
  environment: 'LIVE' | 'FIXTURE';
  persona: string;
  pages?: readonly PageDef[];
}): PageCatalog {
  const defs = input.pages ?? PAGE_DEFS;
  const pages: CatalogPage[] = [];
  for (const def of defs) {
    const rows = input.entries
      .filter((e) => e.page === def.id && e.org === input.org && e.persona === input.persona && e.status !== 'RETIRED')
      .sort((a, b) => a.element.localeCompare(b.element) || a.expression.length - b.expression.length);
    const used = new Set<string>(['root', 'page', 'open', 'constructor']);
    const members: CatalogMember[] = [];
    const add = (m: Omit<CatalogMember, 'name' | 'ref'>, base: string): void => {
      let name = base;
      for (let i = 2; used.has(name); i++) name = `${base}${i}`;
      used.add(name);
      members.push(CatalogMember.parse({ ...m, name, ref: `${def.id}.${name}` }));
    };
    // Regions from scope chains (e.g. the "Contacts" related-list article): named scopes below the root.
    const regions = new Map<string, string>();
    for (const e of rows) {
      const parts = e.scope.split(' › ').map((p) => p.trim());
      let acc = '';
      for (const part of parts) {
        acc = acc ? `${acc}.${part}` : part;
        if (acc === def.rootExpr || part === def.rootExpr) continue;
        if (!regions.has(acc)) regions.set(acc, part);
      }
    }
    const isRoot = (s: string): boolean => s === nameOfCall(def.rootExpr);
    // The page's root region (record `main` / the dialog): what a11y scans and "dialog opens" checks scope to.
    members.push(
      CatalogMember.parse({
        name: 'root',
        ref: `${def.id}.root`,
        kind: 'region',
        ...(roleOfCall(def.rootExpr) ? { role: roleOfCall(def.rootExpr) } : {}),
        ...(nameOfCall(def.rootExpr) ? { accessibleName: nameOfCall(def.rootExpr) } : {}),
        expression: def.rootExpr,
        strategyRank: 1,
        status: 'ACTIVE',
      }),
    );
    for (const [expr] of regions) {
      const role = roleOfCall(expr);
      const name = nameOfCall(expr);
      if (!name) continue;
      add(
        {
          kind: 'region',
          ...(role ? { role } : {}),
          accessibleName: name,
          expression: expr,
          strategyRank: 1,
          status: 'ACTIVE',
        },
        camel(name) + (role ? (ROLE_SUFFIX[role] ?? 'Region') : 'Region'),
      );
    }
    for (const e of rows) {
      const scopeExpr = e.scope
        .split(' › ')
        .map((p) => p.trim())
        .join('.');
      const scopeName = scopeExpr === def.rootExpr ? undefined : nameOfCall(scopeExpr);
      add(
        {
          kind: 'element',
          ...(e.role ? { role: e.role } : {}),
          ...(e.accessibleName ? { accessibleName: e.accessibleName } : {}),
          ...(e.fieldApiName ? { fieldApiName: e.fieldApiName } : {}),
          ...(scopeName ? { scopeName } : {}),
          expression: e.expression,
          strategyRank: e.strategyRank,
          status: e.status === 'RE_VERIFY' ? 'RE_VERIFY' : 'ACTIVE',
          registryElement: e.element,
          lastVerifiedAt: e.lastVerifiedAt,
        },
        memberName(e, scopeName, isRoot),
      );
    }
    pages.push({
      id: def.id,
      className: def.className,
      file: `tests/pages/${def.className}.ts`,
      object: def.object,
      kind: def.kind,
      title: def.title,
      rootExpr: def.rootExpr,
      members,
    });
  }
  return PageCatalog.parse({
    org: input.org,
    orgAlias: input.orgAlias,
    environment: input.environment,
    persona: input.persona,
    generatedFrom: 'locator-registry',
    pages,
  });
}

const doc = (s: string): string => s.replace(/\*\//g, '*\\/');

/** Render one page object (TypeScript). Locator expressions are the registry's, prefixed with `this.page.`. */
export function renderPageObject(p: CatalogPage, cat: PageCatalog): string {
  const lines: string[] = [];
  lines.push(
    `// Generated by sf-qa-agent from the locator registry — do not edit; regenerate with \`qa build\`.`,
    `// Org ${cat.orgAlias} (${cat.environment}), persona ${cat.persona}. ${p.title}.`,
    `import type { Locator, Page } from '@playwright/test';`,
  );
  if (p.kind === 'record') lines.push(`import { openRecord } from '../support/lightning.js';`);
  lines.push('', `export class ${p.className} {`, '  readonly root: Locator;', '');
  lines.push('  constructor(readonly page: Page) {', `    this.root = page.${p.rootExpr};`, '  }', '');
  if (p.kind === 'record') {
    lines.push(
      `  /** Open a ${p.object} by record id (from the data ledger). */`,
      '  async open(recordId: string): Promise<Locator> {',
      `    return openRecord(this.page, '${p.object}', recordId);`,
      '  }',
      '',
    );
  }
  for (const m of p.members) {
    if (m.name === 'root') continue; // the constructor's `root`
    const meta = [
      m.kind === 'region' ? 'region' : (m.fieldApiName ?? m.registryElement ?? ''),
      m.role ? `${m.role} "${m.accessibleName ?? ''}"` : '',
      `rank ${m.strategyRank}`,
      m.lastVerifiedAt ? `verified ${m.lastVerifiedAt.slice(0, 10)}` : '',
      m.status === 'RE_VERIFY' ? 'RE_VERIFY: changed in the org since it was verified' : '',
    ].filter(Boolean);
    lines.push(`  /** ${doc(meta.join(' · '))} */`);
    lines.push(`  get ${m.name}(): Locator {`, `    return this.page.${m.expression};`, '  }', '');
  }
  if (lines[lines.length - 1] === '') lines.pop();
  lines.push('}', '');
  return lines.join('\n');
}

export const hashText = (s: string): string => createHash('sha256').update(s).digest('hex').slice(0, 16);

/** Find a member by ref `<pageId>.<name>`. */
export function findMember(cat: PageCatalog, ref: string): { page: CatalogPage; member: CatalogMember } | undefined {
  const dot = ref.indexOf('.');
  const page = cat.pages.find((p) => p.id === ref.slice(0, dot));
  const member = page?.members.find((m) => m.name === ref.slice(dot + 1));
  return page && member ? { page, member } : undefined;
}

/** The "New" button of a related list on a record page (registry member scoped to the list, else page-level New). */
export function relatedListNewButton(page: CatalogPage, list: string): CatalogMember | undefined {
  const buttons = page.members.filter((m) => m.kind === 'element' && m.role === 'button' && m.accessibleName === 'New');
  return buttons.find((m) => m.scopeName === list) ?? (buttons.length === 1 ? buttons[0] : undefined);
}

/** Write page objects + the catalog under `<root>/tests/pages/` (Prettier-formatted). One artifact per file. */
export async function writePageObjects(
  root: string,
  cat: PageCatalog,
  write: (absPath: string, text: string) => void,
): Promise<{ path: string; hash: string; kind: 'page-object' | 'support' }[]> {
  const out: { path: string; hash: string; kind: 'page-object' | 'support' }[] = [];
  for (const p of cat.pages) {
    if (!p.members.length) continue;
    const abs = joinPath(root, p.file);
    const text = await formatTypeScript(renderPageObject(p, cat), abs);
    write(abs, text);
    out.push({ path: p.file, hash: hashText(text), kind: 'page-object' });
  }
  const catalogText = `${JSON.stringify(cat, null, 2)}
`;
  write(joinPath(root, CATALOG_FILE), catalogText);
  out.push({ path: CATALOG_FILE, hash: hashText(catalogText), kind: 'support' });
  return out;
}

export const CATALOG_FILE = 'tests/pages/page-catalog.json';
const joinPath = (root: string, rel: string): string => join(root, ...rel.split('/'));
